Lemma SINVx_prefix X X' st st1 L BL LS c m i ex :
  INVL X st L BL LS -> ctrl_eq st st1 -> x_idle X' = x_idle X -> s_slots st !! c = Some (m, i) ->
  (m_sizeclass (MR st m) = 63 -> ex = Some m) ->
